import { useMemo, useState } from 'react';

const dateLabel=value=>{if(!value)return'Date unavailable';const date=new Date(`${value}T00:00:00Z`);return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(date);};
const statusStyle=flag=>flag==='NORMAL'?'bg-emerald-100 text-emerald-700':flag==='HIGH'||flag==='LOW'?'bg-amber-100 text-amber-800':'bg-slate-100 text-slate-700';

export default function ExternalBiomarkerHistory({data,onHistory}){
  const [query,setQuery]=useState(''),[status,setStatus]=useState('All'),[panel,setPanel]=useState('All'),[sort,setSort]=useState('Latest');
  const panels=useMemo(()=>['All',...new Set(data.latest.map(item=>item.panel||'Other'))],[data.latest]);
  const rows=useMemo(()=>{let result=data.latest.filter(item=>(`${item.name} ${item.canonicalBiomarkerId}`).toLowerCase().includes(query.toLowerCase()));if(status!=='All')result=result.filter(item=>(item.flag||'UNKNOWN')===status.toUpperCase());if(panel!=='All')result=result.filter(item=>(item.panel||'Other')===panel);if(sort==='Name')result=[...result].sort((a,b)=>a.name.localeCompare(b.name));if(sort==='Abnormal first')result=[...result].sort((a,b)=>Number(['HIGH','LOW'].includes(b.flag))-Number(['HIGH','LOW'].includes(a.flag)));return result;},[data.latest,query,status,panel,sort]);
  return <section className="space-y-4"><div><h3 className="text-xl font-semibold">Biomarker history</h3><p className="text-sm text-slate-500">Latest confirmed observation per biomarker. Source reports are analysed transiently and not retained.</p></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><input aria-label="Search biomarker history" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search biomarker" className="min-h-11 rounded-xl border px-3"/><select aria-label="Filter status" value={status} onChange={e=>setStatus(e.target.value)} className="min-h-11 rounded-xl border px-3">{['All','Normal','High','Low','Unknown'].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Filter panel" value={panel} onChange={e=>setPanel(e.target.value)} className="min-h-11 rounded-xl border px-3">{panels.map(x=><option key={x}>{x}</option>)}</select><select aria-label="Sort history" value={sort} onChange={e=>setSort(e.target.value)} className="min-h-11 rounded-xl border px-3">{['Latest','Name','Abnormal first'].map(x=><option key={x}>{x}</option>)}</select></div>{rows.length===0?<div className="rounded-2xl border border-dashed p-10 text-center text-sm text-slate-500">No confirmed biomarkers match these filters.</div>:<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{rows.map(item=><article key={item.canonicalBiomarkerId} className="min-w-0 rounded-2xl border bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><h4 className="font-semibold leading-5">{item.name}</h4><span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${statusStyle(item.flag)}`}>{item.flag||'UNKNOWN'}</span></div><p className="mt-2 break-words text-2xl font-semibold">{item.value??'—'} <span className="text-sm text-slate-500">{item.unit||''}</span></p><p className="mt-3 text-xs text-slate-500">{dateLabel(item.observationDate)} · {item.reviewStatus.replaceAll('_',' ')}</p><p className="mt-1 text-xs text-slate-500">{item.referenceText?`Reference: ${item.referenceText}`:'Lab reference range not provided'}</p><div className="mt-3 rounded-xl bg-slate-50 p-3 text-xs text-slate-600"><strong className="block text-slate-800">Analysed from lab report</strong>{item.laboratoryName&&<span className="block">{item.laboratoryName}</span>}<span className="block">{item.uploadSource==='CLIENT_SELF_REPORTED'?'Uploaded by Client':'Uploaded by Consultant'}</span>{item.sourcePage&&<span className="block">Source page {item.sourcePage}</span>}</div><button onClick={()=>onHistory(item)} className="mt-4 min-h-11 rounded-lg border px-3 text-xs font-semibold">View history</button></article>)}</div>}</section>;
}
